# ================================================================================

def fitness_shipping_discount(chromosome, target):
    order_total, distance, is_member = chromosome

    # Helper functions for branch distance calculation
    # These functions compute the distance to make a condition TRUE.
    # A distance of 0 means the condition is met.
    # A positive distance means the condition is not met, and a smaller value indicates being closer.
    # The '+ 1' ensures a minimal positive distance when a condition is just barely not met.
    def bdist_lt(left, right):
        # Distance to make 'left < right' true
        return max(0.0, left - right + 1.0)

    def bdist_ge(left, right):
        # Distance to make 'left >= right' true
        return max(0.0, right - left + 1.0)

    def bdist_le(left, right):
        # Distance to make 'left <= right' true
        return max(0.0, left - right + 1.0)

    def bdist_gt(left, right):
        # Distance to make 'left > right' true
        return max(0.0, right - left + 1.0)

    def bdist_is_true(boolean_val):
        # Distance to make 'boolean_val' true
        return 0.0 if boolean_val else 1.0

    def bdist_is_false(boolean_val):
        # Distance to make 'boolean_val' false
        return 0.0 if not boolean_val else 1.0

