    dist_to_make_small_false = bdist_lt(order_total, 50) + bdist_is_false(is_member) # For AND of negated terms

    # --- Simulate the original function's control flow to determine actual_result ---
    # This allows returning 0.0 only when the chromosome actually hits the target.
